def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=5 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                rr,cc=stack.pop(); cells.append((rr,cc))
                for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0<=nr<h and 0<=nc<w and grid[nr][nc]==5 and (nr,nc) not in seen:
                        seen.add((nr,nc)); stack.append((nr,nc))
            r0=min(x for x,y in cells); r1=max(x for x,y in cells); c0=min(y for x,y in cells); c1=max(y for x,y in cells)
            miss=[cc for cc in range(c0,c1+1) if grid[r0][cc]==0]
            if len(miss)!=1: continue
            notch=miss[0]
            # This pattern has solid side/bottom borders and a single gap in its top border.
            if not (all(grid[rr][c0]==5 and grid[rr][c1]==5 for rr in range(r0,r1+1)) and all(grid[r1][cc]==5 for cc in range(c0,c1+1))): continue
            out[r0][notch]=2
            for rr in range(r0+1,r1):
                for cc in range(c0+1,c1):
                    if grid[rr][cc]==0: out[rr][cc]=2
            rayrow=r0-1
            if rayrow>=0:
                if notch-c0 > (c1-c0)/2:
                    for cc in range(0,notch+1):
                        if grid[rayrow][cc]==0: out[rayrow][cc]=2
                else:
                    for cc in range(notch,w):
                        if grid[rayrow][cc]==0: out[rayrow][cc]=2
    return out
